-- Split and backfilled by hand relative to the generator's output.
--
-- The generator emitted one statement that both dropped "template_schedules"
-- and added "launchable_schedules" NOT NULL with no default. On an empty
-- database that works; on a populated one it fails twice over, since a NOT
-- NULL column cannot be added to a table with rows and no default, and the
-- column being dropped in the same breath is the only thing that says which
-- launchable each existing schedule should point at.
--
-- So the column is added nullable, backfilled from the launchable row
-- standing for the template each schedule named, made NOT NULL once every row
-- has a value, and only then is the old column dropped (which takes its own
-- foreign key with it). Names, organizations and timestamps on the new rows
-- are copied from their targets rather than invented, so a listing reads the
-- same before and after.
ALTER TABLE "schedule_occurrences" ADD COLUMN "unified_job_type" character varying NULL;
UPDATE "schedule_occurrences" SET "unified_job_type" = 'job' WHERE "job_id" IS NOT NULL AND "job_id" <> '';
CREATE TABLE "launchables" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "type" character varying NOT NULL, "name" character varying NOT NULL, "organization_launchables" bigint NOT NULL, "project_launchable" bigint NULL, "template_launchable" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "launchables_organizations_launchables" FOREIGN KEY ("organization_launchables") REFERENCES "organizations" ("id") ON DELETE NO ACTION, CONSTRAINT "launchables_projects_launchable" FOREIGN KEY ("project_launchable") REFERENCES "projects" ("id") ON DELETE CASCADE, CONSTRAINT "launchables_templates_launchable" FOREIGN KEY ("template_launchable") REFERENCES "templates" ("id") ON DELETE CASCADE, CONSTRAINT "launchable_exactly_one_target" CHECK (((CASE WHEN template_launchable IS NULL THEN 0 ELSE 1 END) + (CASE WHEN project_launchable IS NULL THEN 0 ELSE 1 END)) = 1));
CREATE UNIQUE INDEX "launchables_project_launchable_key" ON "launchables" ("project_launchable");
CREATE UNIQUE INDEX "launchables_template_launchable_key" ON "launchables" ("template_launchable");
CREATE INDEX "launchable_type_name_organization_launchables" ON "launchables" ("type", "name", "organization_launchables");
INSERT INTO "launchables" ("created_at", "updated_at", "type", "name", "organization_launchables", "template_launchable")
  SELECT "created_at", "updated_at", 'job_template', "name", "organization_templates", "id" FROM "templates" ORDER BY "id";
INSERT INTO "launchables" ("created_at", "updated_at", "type", "name", "organization_launchables", "project_launchable")
  SELECT "created_at", "updated_at", 'project', "name", "organization_projects", "id" FROM "projects" ORDER BY "id";
ALTER TABLE "schedules" ADD COLUMN "launchable_schedules" bigint NULL;
UPDATE "schedules" AS "s" SET "launchable_schedules" = "l"."id" FROM "launchables" AS "l" WHERE "l"."template_launchable" = "s"."template_schedules";
ALTER TABLE "schedules" ALTER COLUMN "launchable_schedules" SET NOT NULL;
ALTER TABLE "schedules" ADD CONSTRAINT "schedules_launchables_schedules" FOREIGN KEY ("launchable_schedules") REFERENCES "launchables" ("id") ON DELETE NO ACTION;
ALTER TABLE "schedules" DROP COLUMN "template_schedules";
